    if x is None:
        return None
    if isinstance(x, bool):
        return '1' if x else '0'
    if isinstance(x, int):
        return str(x)
    if isinstance(x, float):
        # 15 significant digits ~ Excel double round-trip
        return format(x, '.15g')
    # try cast
    try:
        xf=float(x)
        return format(xf, '.15g')
    except Exception:
        return str(x)


def percentile_inc(values, k):
    # Excel PERCENTILE (aka PERCENTILE.INC)
    xs=sorted(values)
    n=len(xs)
    if n==0:
        raise ValueError('percentile of empty')
    if n==1:
        return float(xs[0])
    if k<=0:
        return float(xs[0])
    if k>=1:
        return float(xs[-1])
    r=(n-1)*k
    lo=int(r)
    hi=lo+1
    frac=r-lo
    return float(xs[lo]) + (float(xs[hi]) - float(xs[lo]))*frac


def median(values):
    xs=sorted(values)
    n=len(xs)
    if n==0:
        raise ValueError('median of empty')
    mid=n//2
    if n%2==1:
        return float(xs[mid])
    return (float(xs[mid-1])+float(xs[mid]))/2.0


